mapper.select:
select
id, node_id, vendor_account_id, resource_ip, resource_port, resource_user_name, resource_password,
transferable_quantity, available_status, is_deleted, create_user, update_user, create_time, update_time, status
from relay_resource

    1 = 1 and is_deleted = 0

        and id = #{id}


        and node_id = #{nodeId}


        and vendor_account_id = #{vendorAccountId}


        and resource_ip = #{resourceIp}


        and resource_port = #{resourcePort}


        and resource_user_name = #{resourceUserName}


        and resource_password = #{resourcePassword}


        and transferable_quantity = #{transferableQuantity}


        and available_status = #{availableStatus}

select
id, node_id, vendor_account_id, resource_ip, resource_port, resource_user_name, resource_password,
transferable_quantity, available_status, is_deleted, create_user, update_user, create_time, update_time, status
from relay_resource

    1 = 1 and is_deleted = 0

        and id = #{dto.id}


        and node_id = #{dto.nodeId}


        and vendor_account_id = #{dto.vendorAccountId}


        and resource_ip = #{dto.resourceIp}


        and resource_port = #{dto.resourcePort}


        and resource_user_name = #{dto.resourceUserName}


        and resource_password = #{dto.resourcePassword}


        and transferable_quantity = #{dto.transferableQuantity}


        and available_status = #{dto.availableStatus}


limit #{limit}

select rr.*, rn.node_name as nodeName from relay_resource rr left join relay_node rn on rr.node_id = rn.id and rn.is_deleted = 0
rr.is_deleted = 0
and rr.resource_ip like concat('%', #{dto.resourceIpLike}, '%')
and rr.node_id = #{dto.nodeId}
and rr.available_status = #{dto.availableStatus}
order by rr.create_time desc

mapper.update:
update relay_resource
set available_status = case when available_status = 1 then 0 else 1 end
where id = #{id}
